import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  Euler,
  Vector3,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const {
    textContent,
    scenePosition,
    behavior,
  } = config;

  // Position, rotation, scale
  const pos = new Vector3(
    scenePosition?.x ?? 0,
    scenePosition?.y ?? 0,
    scenePosition?.z ?? 0
  );
  const rot = new Euler(
    scenePosition?.rotation?.x ?? 0,
    scenePosition?.rotation?.y ?? 0,
    scenePosition?.rotation?.z ?? 0
  );
  const sca = new Vector3(
    scenePosition?.scale?.x ?? 1,
    scenePosition?.scale?.y ?? 1,
    scenePosition?.scale?.z ?? 1
  );

  // Container group
  const group = new Group();
  group.position.copy(pos);
  group.rotation.copy(rot);
  group.scale.copy(sca);

  // --- Background plane ---
  // Load texture from asset
  const textureUrl = '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Determine plane size based on texture aspect ratio
  // Default to width 2 if image not yet loaded (texture image may not be available synchronously)
  const width = 2;
  let height = 1.25; // fallback aspect 1.6:1
  if (texture.image) {
    const aspect = texture.image.width / texture.image.height;
    height = width / aspect;
  }

  const bgGeometry = new PlaneGeometry(width, height);
  const bgMaterial = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });
  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  group.add(bgMesh);

  // --- Text overlay ---
  // Render "Collection 3" using the font atlas
  // Text style: display font Lora, 39px, weight 400, colour paper (#e8ecf2)
  const textMesh = ctx.fontAtlas(textContent, {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
    baseline: 'middle',
    // Use the atlas region hint (optional, fontAtlas may accept source rect)
    atlasRegion: {
      atlas: 0,
      sourceRect: { x: 0, y: 0, width: 512, height: 320 },
    },
  });

  // Scale the text to fit within the card; assume a reasonable base scale
  // The fontAtlas returns an Object3D; we can scale it relative to the card size
  // Using a uniform scale factor to keep size readable
  textMesh.scale.set(0.004, 0.004, 0.004); // Tweak based on scene units
  textMesh.position.set(0, 0, 0.01); // Slight forward z-offset to avoid z-fighting
  group.add(textMesh);

  // --- User data handlers (none, but required structure) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    bgGeometry.dispose();
    bgMaterial.dispose();
    if (texture) texture.dispose();

    // Dispose any nested meshes in the text object (if ctx.fontAtlas creates internal meshes)
    textMesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });

    // Kill any GSAP timelines associated with this node (none in this static element)
    // The module does not create any animations, so no GSAP cleanup needed.
  };

  return group;
}
